    <script>
        // 安全获取对象值的函数
        function SafeGetValue(obj, path, defaultValue = "N/A") {
            let keys = Array.isArray(path) ? path : path.split('.');
            let current = obj;
            for (let i = 0; i < keys.length; i++) {
                if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                    return defaultValue;
                }
                current = current[keys[i]];
            }
            return current === undefined || current === null ? defaultValue : current;
        }

        // 更新文本值的函数
        function updateTextValue(elementId, rawValue) {
            const element = document.getElementById(elementId);
            if (!element) return;
            let displayValue = Array.isArray(rawValue) ? rawValue[0] : rawValue;
            let valueStr = String(displayValue).replace(/\s*\([^)]*\)$/, '').trim();
            const parts = valueStr.split('->');
            element.innerText = parts[parts.length - 1].trim();
        }

        // 更新进度条的函数
        function updateProgressBar(elementId, rawValue, min, max) {
            const progressBar = document.getElementById(elementId);
            if (!progressBar) return;
            let numericValue;
            if (Array.isArray(rawValue)) {
                numericValue = parseFloat(rawValue[0]);
            } else {
                numericValue = parseFloat(String(rawValue).split('->').pop());
            }
            if (isNaN(numericValue)) {
                numericValue = min;
            }
            numericValue = Math.max(min, Math.min(max, numericValue));
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
        }

